package main
import (
  "net/http"
  "io/ioutil"
)

func fetch(url string) string {
  resp, _ := http.Get(url)
  body, _ := ioutil.ReadAll(resp.Body)
  defer resp.Body.Close()
  return string(body)
}

package repo

import (
  "database/sql"
  "fmt"
)

func GetUser(db *sql.DB, username string) (int, error) {
  query := fmt.Sprintf("SELECT id FROM users WHERE username = '%s'", username)
  row := db.QueryRow(query)
  var id int
  if err := row.Scan(&id); err != nil {
    return 0, err
  }
  return id, nil
}

package main

import "database/sql"

func GetAllUsers(db *sql.DB) []User {
  users := []User{}
  ids := []int{1, 2, 3, 4, 5}
  for _, id := range ids {
    row := db.QueryRow("SELECT * FROM users WHERE id = ?", id)
    var u User
    row.Scan(&u.ID, &u.Name)
    users = append(users, u)
  }
  return users
}

